def r(name, slug, pub, summary, industry, country, emp, domain="", contacts=None, li="", phone="", email="", csrc="", status="CURRENT", conf=90,
      reason="", pitch="", signals="", notes=""):
    return dict(company_name=name, company_domain=domain, industry=industry, hq_country=country, employee_count=emp, employee_count_source_url=B+slug+"/",
        vendor=V, evidence_type=CS, evidence_summary=summary, source_url=B+slug+"/", source_publication_date=pub,
        status=status, status_reason=reason or f"Live named TimeCamp customer story (online since at least {pub})", confidence_score=conf,
        contacts=contacts or [], company_linkedin=li, company_phone=phone, public_email=email, contact_source_url=csrc,
        pitch_angle=pitch, workforce_signals=signals, notes=(notes+" "+NOTE).strip())
